const authorHelp=document.getElementById('authorHelp');const authorModal=document.getElementById('authorModal');function openAuthor(){authorModal.classList.add('open');authorModal.setAttribute('aria-hidden','false')}function closeAuthor(){authorModal.classList.remove('open');authorModal.setAttribute('aria-hidden','true');authorHelp.focus()}authorHelp.addEventListener('click',openAuthor);document.querySelectorAll('[data-close-author]').forEach(item=>item.addEventListener('click',closeAuthor));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&authorModal.classList.contains('open'))closeAuthor()});
